PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3id.org/coolstuff/ref#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z (str(?lbl) AS ?s) WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?lbl }
  FILTER(str(?lbl) LIKE "%DataCenter%basement%6%" || str(?lbl) LIKE "%ZN_6%")
}

PREFIX ref: <http://w3id.org/coolstuff/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?p (str(?l) AS ?s) WHERE {
  ?p ref:hasTimeseriesId ?ts .
  OPTIONAL { ?p rdfs:label ?l }
  FILTER(str(?l) LIKE "%ZN_6%")
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?z (str(?l) AS ?s) WHERE {
  ?z rdfs:label ?l .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3id.org/coolstuff/ref#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?point ?type ?ts WHERE {
  ?point brick:hasLocation <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z06> .
  ?point rdf:type ?type .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
